mapper.select:
WITH route_context AS (
    SELECT
        r.route_id,

        ST_Transform(
            ST_LineMerge(r.geom),
            32650
        ) AS original_metric_line

    FROM public.routes r

    WHERE r.route_id = #{routeId}
      AND ST_GeometryType(
            ST_LineMerge(r.geom)
          ) = 'ST_LineString'
),

source_progress AS (
    SELECT
        original_metric_line,

        CAST(
            #{sourceStartProgressRatio}
            AS double precision
        )
        +
        CAST(
            #{progressRatio}
            AS double precision
        )
        *
        (
            CAST(
                #{sourceEndProgressRatio}
                AS double precision
            )
            -
            CAST(
                #{sourceStartProgressRatio}
                AS double precision
            )
        ) AS source_progress_ratio

    FROM route_context
),

interpolated_position AS (
    SELECT
        ST_Transform(
            ST_LineInterpolatePoint(
                original_metric_line,
                source_progress_ratio
            ),
            4326
        ) AS position

    FROM source_progress
)

SELECT
    ST_X(position) AS longitude,
    ST_Y(position) AS latitude

FROM interpolated_position
